using System.Data;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Catalog;using MediDesk.Common.Contracts.Finance;using Microsoft.Data.SqlClient;namespace MediDesk.Data.Repositories;public sealed class AccountRepository(SqlConnectionFactory f):IAccountRepository{public async Task<PagedResponse<AccountEntryDto>>GetPageAsync(AccountQuery q,CancellationToken ct){var w="IsDeleted=0 AND (@S IS NULL OR AccountName LIKE @L OR VoucherNumber LIKE @L)";await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand($"SELECT COUNT(1) FROM dbo.AccountEntries WHERE {w};SELECT Id,VoucherNumber,EntryType,AccountName,PaymentMode,Amount,COALESCE(Reference,''),CONVERT(varchar(33),CreatedAtUtc,127),CASE WHEN EntryType IN ('Receipt','Income') THEN 'Credit' ELSE 'Debit' END FROM dbo.AccountEntries WHERE {w} ORDER BY CreatedAtUtc DESC OFFSET @O ROWS FETCH NEXT @P ROWS ONLY",c);cmd.Parameters.Add("@S",SqlDbType.NVarChar,160).Value=(object?)q.Search??DBNull.Value;cmd.Parameters.Add("@L",SqlDbType.NVarChar,170).Value=q.Search is null?DBNull.Value:$"%{q.Search}%";cmd.Parameters.Add("@O",SqlDbType.Int).Value=(q.Page-1)*q.PageSize;cmd.Parameters.Add("@P",SqlDbType.Int).Value=q.PageSize;await using var rd=await cmd.ExecuteReaderAsync(ct);await rd.ReadAsync(ct);var total=rd.GetInt32(0);await rd.NextResultAsync(ct);var a=new List<AccountEntryDto>();while(await rd.ReadAsync(ct))a.Add(new(rd.GetInt64(0),rd.GetString(1),rd.GetString(2),rd.GetString(3),rd.GetString(4),rd.GetDecimal(5),rd.GetString(6),rd.GetString(7),rd.GetString(8)));return new(a,q.Page,q.PageSize,total);}public async Task<AccountEntryDto>CreateAsync(CreateAccountEntryRequest x,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("INSERT dbo.AccountEntries(VoucherNumber,EntryType,AccountName,PaymentMode,Amount,Reference,CreatedByUserId)OUTPUT INSERTED.Id VALUES(CONCAT('VCH-',YEAR(SYSUTCDATETIME()),'-',RIGHT('000000'+CAST(NEXT VALUE FOR dbo.AccountVoucherSequence AS VARCHAR(6)),6)),@T,@N,@M,@A,@R,@U)",c);cmd.Parameters.Add("@T",SqlDbType.NVarChar,20).Value=x.EntryType;cmd.Parameters.Add("@N",SqlDbType.NVarChar,160).Value=x.AccountName;cmd.Parameters.Add("@M",SqlDbType.NVarChar,20).Value=x.PaymentMode;cmd.Parameters.Add("@A",SqlDbType.Decimal).Value=x.Amount;cmd.Parameters.Add("@R",SqlDbType.NVarChar,120).Value=(object?)x.Reference??DBNull.Value;cmd.Parameters.Add("@U",SqlDbType.BigInt).Value=u;var id=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));return (await GetPageAsync(new AccountQuery(PageSize:200),ct)).Items.First(x=>x.Id==id);}}

